import json, pathlib, re

ROOT = pathlib.Path(__file__).resolve().parent.parent
DIR = ROOT / "src" / "pages" / "limudim" / "timer"
SUF = " | כלים ללימודים"
MAIN = (DIR / "index.html").read_text(encoding="utf-8")
TOOL = re.search(r'(<div class="tool">.*?\n</div>)\s*\n', MAIN, re.S).group(1)
MM = json.loads(re.match(r"\s*<!--meta\s*(\{.*?\})\s*-->", MAIN, re.S).group(1))
CSS = '<link rel="stylesheet" href="/assets/seo-txt.css"><link rel="stylesheet" href="/assets/limudim-shaon.css">'
NAMES = {1: "דקה", 2: "2 דקות", 3: "3 דקות", 5: "5 דקות", 10: "10 דקות", 15: "15 דקות", 20: "20 דקות", 30: "30 דקות"}


def slug(n): return "daka" if n == 1 else f"{n}-dakot"


def links(cur):
    a = '<a href="/limudim/timer/">⏲ טיימר לכל משך</a>' + "".join(
        f'<a href="/limudim/timer/{slug(n)}/"' + (' aria-current="page"' if n == cur else "") + f">{'טיימר ' + NAMES[n]}</a>" for n in NAMES)
    a += '<a href="/limudim/shaon-etzer/">⏱ שעון עצר</a>'
    return f'<nav class="gr-links tm-links" aria-label="עוד טיימרים">{a}</nav>'


def faq_ld(faq):
    return json.dumps({"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [
        {"@type": "Question", "name": q, "acceptedAnswer": {"@type": "Answer", "text": re.sub(r"<[^>]+>", "", a)}} for q, a in faq]}, ensure_ascii=False)


